<template>
  <q-list bordered>
    <!-- Multi-Org Switcher (M2, SD 2860679170 §4.2) previously lived here as
         an inline dropdown — moved to a dedicated header icon
         (HeaderOrgSwitchButton.vue, top-right, next to the sub-org
         switcher) per the Product Owner's binding placement correction
         (DOCB-13399): the header is now the ONLY switch path. This list
         still owns the pre-existing, UNRELATED sub-org switcher below
         (parent org -> child sub-orgs) — that one was never misplaced and
         stays exactly where it was. -->
    <template v-for="(organization, index) in organizations" :key="index">
      <q-item :clickable="organization.sub_organisations.length > 0">
        <q-item-section avatar>
          <q-avatar size="32px" class="user-avatar-background">
            <span class="user-item-initials">
              {{ getInitials(userFullName) }}
            </span>
          </q-avatar>
        </q-item-section>
        <q-item-section>
          <span class="user-profile-name">{{ userFullName }}</span>
          <span>{{ organization.name }}</span>
        </q-item-section>
        <q-item-section side v-if="organization.sub_organisations.length > 0">
          <q-icon name="keyboard_arrow_right" />
        </q-item-section>
        <q-menu
          v-if="organization.sub_organisations.length > 0"
          anchor="top end"
          self="top start"
          :offset="[1, 0]"
          style="border-radius: 4px"
          class="no-shadow gray-border"
        >
          <q-list bordered>
            <template
              v-for="(
                sub_organization, index_sub
              ) in organization.sub_organisations"
              :key="index_sub"
            >
              <q-item
                clickable
                @click="setSubOrg(sub_organization)"
                v-ripple
                :active="sub_organization.id === sub_org_id"
              >
                <q-item-section avatar>
                  <q-icon
                    v-if="sub_organization.id === sub_org_id"
                    name="check"
                  />
                </q-item-section>
                <q-item-section class="text-capitalize">{{
                  sub_organization.name.toLowerCase()
                }}</q-item-section>
              </q-item>
            </template>
          </q-list>
        </q-menu>
      </q-item>
    </template>

    <q-separator />
    <div data-test="language-dropdown-in-menu">
      <LanguageDropdown />
    </div>
    <div data-test="dark-mode-in-menu">
      <DarkMode />
    </div>
    <q-item
      clickable
      @click="aboutDialog = true"
      v-ripple
      data-test="about-option"
    >
      <q-item-section avatar>
        <q-icon class="icon-grey" name="info" />
      </q-item-section>
      <q-item-section class="text-capitalize">{{
        $t('about') || 'About'
      }}</q-item-section>
    </q-item>
    <q-item
      clickable
      @click="profileDialog = true"
      v-ripple
      data-test="settings-option"
    >
      <q-item-section avatar>
        <q-icon class="icon-grey" name="settings" />
      </q-item-section>
      <q-item-section class="text-capitalize">{{
        $t('settings').toLowerCase()
      }}</q-item-section>
    </q-item>
    <q-item
      v-if="hasDocNetAccess"
      clickable
      @click="openTeamsLink"
      v-ripple
      data-test="link-teams-option"
    >
      <q-item-section avatar>
        <q-icon class="icon-grey" name="groups" />
      </q-item-section>
      <q-item-section>{{
        $t('teams_link_code_menu_item')
      }}</q-item-section>
    </q-item>
    <q-separator />
    <q-item clickable @click="logout()" v-ripple data-test="logout-button">
      <q-item-section avatar>
        <q-icon
          class="icon-grey"
          name="power_settings_new"
          data-test="logout-icon"
        />
      </q-item-section>
      <q-item-section class="text-capitalize" data-test="logout-text">{{
        $t('logout')
      }}</q-item-section>
    </q-item>
  </q-list>
  <!-- <div class="row no-wrap q-py-md">
    <div class="column items-center" style="min-width: 180px">
      <q-avatar size="90px" class="user-avatar-background">
        <span class="user-item-initials">
          {{ getInitials(userFullName) }}
        </span>
      </q-avatar>
      <div class="text-subtitle1 q-mt-sm">{{ userFullName }}</div>
      <label class="row q-ma-sm" @click="profileDialog = true">
        <q-icon
          name="edit"
          size="16px"
          color="primary"
          class="mt-3 cursor-pointer"
        >
          <q-tooltip>{{ $t('edit') }}</q-tooltip>
        </q-icon>
        <span class="cursor-pointer text-primary">{{ $t('edit') }}</span>
      </label>
      <div class="row" style="margin-top: 20%">
        
        <f-btn
          square="true"
          @click="logout()"
          icon="power_settings_new"
          class="logout-btn"
        />
      </div>
    </div>
  </div> -->

  <!-- Profile Dialog starts -->
  <q-dialog
    persistent
    v-model="profileDialog"
    @keydown.esc="profileDialog = false"
  >
    <EditProfile @refreshClicked="refreshClicked" @popClosed="popupClosed" />
  </q-dialog>
  <!-- Profile dialog ends -->

  <!-- About Dialog starts -->
  <q-dialog
    v-model="aboutDialog"
    @keydown.esc="aboutDialog = false"
  >
    <q-card style="min-width: 500px; min-height: 400px">
      <VersionsList :app_version="appVersion" />
    </q-card>
  </q-dialog>
  <!-- About dialog ends -->

  <!-- refresh Warning -->
  <q-dialog
    v-model="refresh_warning"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('change_lost_warning') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
          @click="refresh_warning = false"
        />
        <f-btn
          data-cy="done"
          :label="$t('proceed')"
          @click="refreshSettings(true)"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- END Un Save Changes Warning -->
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { Acl } from 'src/core/acls/index';
import { ApiExceptions } from 'src/exceptions/index';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { UserSubOrg } from 'src/utils/organization/index';
import EditProfile from 'src/pages/User/Edit-Profile.vue';
import {
  useUserStore,
  useSettingStore,
  useLangOriginDropdownStore,
  useDocumentStore,
  useDatePatternDropdownStore,
} from 'src/store/main';
import {
  getUserDetailFromkey,
  isUserAdmin,
  isSupplierUser,
  hasDocNetAccess,
} from 'src/utils/UserDetails';
import LanguageDropdown from 'src/components/LayoutHeader/LanguageDropdown.vue';
import DarkMode from 'src/components/LayoutHeader/AccountDropdown/darkModeOption.vue';
import VersionsList from 'src/components/LayoutHeader/VersionsList.vue';
import type { dynamicObj } from 'src/pages/assets';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  mixins: [cache, helperMixin],
  props: {},
  emits: ['closeUserMenu'],
  components: {
    EditProfile,
    DarkMode,
    LanguageDropdown,
    VersionsList,
  },
  data() {
    return {
      is_sub_org: ref(false),
    };
  },
  computed: {
    hasDocNetAccess(): boolean {
      return hasDocNetAccess(this.user_settings);
    },
  },
  mounted: async function () {
    await this.init();
    // window.addEventListener('storage', this.storageChangeEvent);
    document.addEventListener('click', this.handleClickOutside);
    document.addEventListener('openAboutDialog', this.handleOpenAbout);
  },
  unmounted: function () {
    // window.removeEventListener('storage', this.storageChangeEvent);
    document.removeEventListener('click', this.handleClickOutside);
    document.removeEventListener('openAboutDialog', this.handleOpenAbout);
  },
  methods: {
    getInitials(fullname: string) {
      var names = fullname.split(' '),
        initials: string = names[0].substring(0, 1).toUpperCase();

      if (names.length > 1) {
        initials += names[names.length - 1].substring(0, 1).toUpperCase();
      }
      return initials;
    },
    async init() {
      try {
        this.loading = true;
        this.getSubInfo();
        await this.refreshSettings();
        await this.getSubOrgId();
        this.refreshUserInfo();
        this.getLanguageIfEmpty();
        this.getDatePatterns();
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    // storageChangeEvent(e: any) {
    //   this.handleSessionStorageChange(e);
    // },

    getSubOrgName(sub_organisations: any) {
      let name;
      sub_organisations.map((org: any) => {
        if (org.id === this.sub_org_id) {
          name = org.name as string;
        }
      });
      return name;
    },
    getSubInfo() {
      if (this.organizations && this.organizations.length > 0) {
        this.organizations.map((org: any) => {
          if (org.sub_organisations.length > 0) {
            this.is_sub_org = true;
          } else {
            this.is_sub_org = false;
          }
        });
      } else {
        this.is_sub_org = false;
      }
    },

    // async handleSessionStorageChange(event: any) {
    //   try {
    //     this.startSettingsFetch();
    //     await this.refreshAndGetSubOrgId();
    //   } catch (err: any) {
    //     logError(err);
    //   } finally {
    //   }
    // },

    async getDatePatterns() {
      if (this.date_pattern_loaded) {
        return;
      }
      await this.getDatePatternOptions();
    },

    async setSubOrg(selected_sub_org: any) {
      try {
        this.showLoading();
        const id = String(selected_sub_org.id);
        if (!id) {
          notify.error(this.$t('NO_ORG_SELECTED'));
          return;
        }
        await UserSubOrg.setSubOrgId(id);
        await this.refreshAndGetSubOrgId();
        this.$router.go(0);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
      return;
    },

    refreshUserInfo() {
      this.profileDialog = false;
      const id = getUserDetailFromkey('id');
      this.isUserAdmin = getUserDetailFromkey('is_organisation_admin');

      if (id) {
        this.updateUserName();
      } else {
        this.logout();
      }
    },

    async refreshSettings(clear_sessions = false) {
      await this.startSettingsFetch();
      this.refresh_warning = false;
      if (!clear_sessions) {
        return;
      }
      this.clearStorageForRefresh();
      await Acl.fetch();
      await this.refreshUserOrganizations();
      // doc store

      const doc_store = useDocumentStore();
      doc_store.resetDocStore(this.$route.fullPath);
      this.$router.go(0);
    },

    refreshClicked() {
      const route_name = this.$route.path;
      const nonwarningRoutes = ['/dashboard', '/setting'];
      if (nonwarningRoutes.includes(route_name)) {
        this.profileDialog = false;
        this.refreshSettings(true);
        return;
      }
      this.refresh_warning = true;
    },

    hasSubOrganizations() {
      if (
        this.organizations[0] &&
        this.organizations[0].hasOwnProperty('sub_organisations') &&
        this.organizations[0].sub_organisations.length > 0
      ) {
        return true;
      }
      return false;
    },
    popupClosed() {
      this.$emit('closeUserMenu');
    },
    handleClickOutside(event: any) {
      const el = document.getElementById('user-setting-list');

      if (!el) return;

      // Don't close the menu if any dialog is open
      if (this.profileDialog || this.aboutDialog || this.refresh_warning) {
        return;
      }

      const isVisible =
        el &&
        !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length) &&
        getComputedStyle(el).visibility !== 'hidden' &&
        getComputedStyle(el).display !== 'none' &&
        getComputedStyle(el).opacity !== '0';

      // Check if click is outside the element
      const clickedOutside = !el.contains(event.target);

      const clickedDarkMode =
        event.target.id === 'dark_mode_box' ||
        event.target.id === 'dark_mode_icon' ||
        event.target.id === 'dark_mode_text';

      if (isVisible && clickedOutside && !clickedDarkMode) {
        this.$emit('closeUserMenu');
      }
    },
    handleOpenAbout() {
      this.aboutDialog = true;
    },
    openTeamsLink() {
      this.$emit('closeUserMenu');
      this.$router.push('/doc-net/link-teams');
    },
  },
  setup() {
    const user_store = useUserStore();
    const {
      updateUserName,
      getUserOrganizations,
      getSubOrgId,
      refreshAndGetSubOrgId,
      refreshUserOrganizations,
    } = user_store;
    const { userFullName, organizations, sub_org_id, main_orgainzation } =
      storeToRefs(user_store);

    const settings_store = useSettingStore();
    const { startSettingsFetch } = settings_store;
    const { user_settings } = storeToRefs(settings_store);

    const language_origin_dropdown = useLangOriginDropdownStore();
    const { getLanguageIfEmpty } = language_origin_dropdown;

    const date_pattern_dropdown = useDatePatternDropdownStore();
    const { getDatePatternOptions } = date_pattern_dropdown;
    const { date_pattern_loaded } = storeToRefs(date_pattern_dropdown);

    return {
      startSettingsFetch,
      refreshUserOrganizations,
      refreshAndGetSubOrgId,
      date_pattern_loaded,
      getDatePatternOptions,
      getLanguageIfEmpty,
      getUserOrganizations,
      updateUserName,
      getSubOrgId,
      settings_store,
      main_orgainzation,
      sub_org_id,
      userFullName,
      organizations,
      user_settings,
      refresh_warning: ref(false),
      profileDialog: ref(false),
      aboutDialog: ref(false),
      isUserAdmin: ref(''),
      link: ref('inbox'),
      loading: ref(false),
      isSupplierUser,
      appVersion: process.env.APP_VUE_CURRENT_VERSION || 'unknown',
    };
  },
});
</script>

