<template>
  <q-drawer
    v-if="shouldShowSidebar"
    v-model="drawer"
    show-if-above
    :mini="!drawer || miniState"
    :width="250"
    :breakpoint="500"
    bordered
    class="highlighted-back"
  >
    <div v-if="isMobile()">
      <q-avatar
        class="cursor-pointer big-fellow-icon"
        square
        @click="drawer = !drawer"
      >
        <img
          :src="
            $q.dark.isActive
              ? '/images/docbits-black.svg'
              : '/images/docbits.svg'
          "
          target="_blank"
          rel="noopener noreferrer"
          class="icon-width"
        />
      </q-avatar>
    </div>

    <div v-else>
      <q-avatar
        class="cursor-pointer big-fellow-icon"
        square
        v-if="!miniState"
        @click="miniState = true"
      >
        <img
          :src="
            $q.dark.isActive
              ? '/images/docbits-black.svg'
              : '/images/docbits.svg'
          "
          target="_blank"
          rel="noopener noreferrer"
          class="icon-width"
        />
      </q-avatar>
      <q-avatar
        square
        class="cursor-pointer small-fellow-icon"
        v-if="miniState"
        data-test="sidebar-expand-toggle"
        @click="miniState = false"
      >
        <img src="/icons/LOGO.svg" target="_blank" rel="noopener noreferrer" />
      </q-avatar>
    </div>

    <!-- EDIT MODE -->
    <div
      v-if="sidebarEditMode && !miniState"
      class="scroll-menu sidebar-edit-container"
      :class="!isMobile() ? 'thin-scrollbar' : ''"
    >
      <div class="sidebar-edit-header">
        <span class="sidebar-edit-title">Customize</span>
        <div class="sidebar-edit-actions">
          <span class="sidebar-edit-reset" @click="resetSidebarPreferences"
            >Reset</span
          >
          <span class="sidebar-edit-done" @click="exitEditMode">Done</span>
        </div>
      </div>
      <draggable
        v-model="editMenuList"
        ghost-class="sidebar-drag-ghost"
        drag-class="sidebar-drag-active"
        :animation="150"
        @end="onDragEnd"
        class="sidebar-edit-list"
      >
        <div
          v-for="element in editMenuList"
          :key="element.name"
          class="sidebar-edit-item"
          :class="{ 'sidebar-edit-item-hidden': !element._visible }"
        >
          <div class="sidebar-drag-handle">
            <Icon
              icon="mdi:drag-vertical"
              class="size-4 text-muted-foreground"
            />
          </div>
          <NavIcon
            v-if="
              typeof element.icon === 'string' &&
              !element.icon.startsWith('img:')
            "
            :icon="element.icon"
            :isActive="false"
            class="menu-icon-size"
          />
          <component
            v-else-if="typeof element.icon !== 'string'"
            class="menu-icon-size"
            :is="element.icon"
            :isActive="false"
          />
          <span class="sidebar-edit-label">
            {{
              element.name === 'doc_operator'
                ? $t(element.label)
                : $t(element.label).toLowerCase()
            }}
          </span>
          <q-toggle
            :model-value="element._visible"
            size="xs"
            dense
            @update:model-value="toggleItemVisibility(element.name)"
            class="sidebar-edit-toggle"
          />
        </div>
      </draggable>
    </div>

    <!-- TOP ITEMS (Normal Mode) -->
    <q-list
      v-else
      padding
      class="scroll-menu"
      :class="!isMobile() ? 'thin-scrollbar' : ''"
    >
      <template v-for="(menuItem, index) in menuList" :key="index">
        <q-item
          clickable
          @click="navigateTo(menuItem.to)"
          :active="isActive(menuItem.to)"
          v-ripple
          active-class="active-text"
          :id="menuItem.name"
          :data-test="'sidebar-item-' + menuItem.name"
        >
          <q-item-section avatar>
            <NavIcon
              v-if="
                typeof menuItem.icon === 'string' &&
                !menuItem.icon.startsWith('img:')
              "
              :icon="menuItem.icon"
              :isActive="isActive(menuItem.to)"
              class="menu-icon-size"
            />
            <q-icon
              v-else-if="
                typeof menuItem.icon === 'string' &&
                menuItem.icon.startsWith('img:')
              "
              :color="
                isActive(menuItem.to)
                  ? 'primary'
                  : $q.dark.isActive
                    ? 'color-icon-grey'
                    : 'color-dark-grey'
              "
              :name="menuItem.icon"
            />
            <component
              v-else
              class="menu-icon-size"
              :is="menuItem.icon"
              :isActive="isActive(menuItem.to)"
            />
            <q-badge
              v-if="menuItem.name === 'tasks' && open_task_count > 0"
              color="red"
              class="badge-solid"
              style="position: absolute; z-index: 1; top: 4px; right: 4px"
              :label="open_task_count"
            />
            <q-tooltip class="text-capitalize">{{
              menuItem.name === 'doc_operator'
                ? $t(menuItem.label)
                : $t(menuItem.label).toLowerCase()
            }}</q-tooltip>
          </q-item-section>
          <q-item-section>
            <span class="text-capitalize">{{
              menuItem.name === 'doc_operator'
                ? $t(menuItem.label)
                : $t(menuItem.label).toLowerCase()
            }}</span>
          </q-item-section>
        </q-item>
        <q-separator :key="'sep' + index" v-if="menuItem.separator" />
      </template>
    </q-list>

    <div class="fixed-bottom bottom-items">
      <q-separator />
      <q-list>
        <div v-if="!isMobile()">
          <template v-for="(bottomItem, index) in bottomItems" :key="index">
            <q-item
              clickable
              @click="bottomItem.name !== 'user' && navigateTo(bottomItem.to)"
              :active="isActive(bottomItem.to)"
              v-ripple
              active-class="active-text"
              :id="bottomItem.name"
              :data-test="'sidebar-item-' + bottomItem.name"
            >
              <q-item-section avatar>
                <NavIcon
                  :icon="bottomItem.icon"
                  :isActive="isActive(bottomItem.to)"
                  class="menu-icon-size"
                />
                <q-tooltip class="text-capitalize">{{
                  $t(bottomItem.label).toLowerCase()
                }}</q-tooltip>
              </q-item-section>
              <q-item-section>
                <span class="text-capitalize">{{
                  $t(bottomItem.label).toLowerCase()
                }}</span>
              </q-item-section>
              <q-menu
                v-if="bottomItem.name == 'user'"
                style="border-radius: 4px"
                class="no-shadow gray-border"
                anchor="bottom right"
                self="bottom left"
                v-model="showUserMenu"
                persistent
                id="user-setting-list"
                data-test="sidebar-user-menu"
              >
                <UserDropDown @closeUserMenu="showUserMenu = false" />
              </q-menu>
            </q-item>
            <q-separator v-if="bottomItem.separator" :key="'sep' + index" />
          </template>
        </div>
        <div v-else>
          <template v-for="(bottomItem, index) in bottomItems" :key="index">
            <q-item
              v-if="bottomItem.name !== 'notifications'"
              clickable
              @click="navigateTo(bottomItem.to)"
              :active="isActive(bottomItem.to)"
              v-ripple
              active-class="active-text"
              :id="bottomItem.name"
            >
              <q-item-section avatar>
                <NavIcon
                  :icon="bottomItem.icon"
                  :isActive="isActive(bottomItem.to)"
                  class="menu-icon-size"
                />
                <q-tooltip class="text-capitalize">{{
                  $t(bottomItem.label).toLowerCase()
                }}</q-tooltip>
              </q-item-section>
              <q-item-section>
                <span class="text-capitalize">{{
                  $t(bottomItem.label).toLowerCase()
                }}</span>
              </q-item-section>
            </q-item>
          </template>
        </div>
      </q-list>
      <q-separator />
      <!-- Customize Sidebar Button -->
      <q-item
        v-if="!miniState && !sidebarEditMode"
        clickable
        dense
        v-ripple
        @click="enterEditMode"
        class="sidebar-customize-btn"
        data-test="sidebar-customize-btn"
      >
        <q-item-section avatar>
          <NavIcon
            icon="mdi:pencil-outline"
            :isActive="false"
            class="menu-icon-size"
          />
        </q-item-section>
        <q-item-section>
          <span class="text-capitalize text-xs text-muted-foreground"
            >customize</span
          >
        </q-item-section>
        <q-item-section side @click.stop>
          <HelpLink
            name="customizable_sidebar"
            data-test="help-link-customizable-sidebar"
          />
        </q-item-section>
      </q-item>
      <div @click="showAppVersion = true">
        <p class="text-center q-pt-md ellipsis q-px-sm cursor-pointer">
          {{ app_version }}
        </p>
        <q-tooltip>
          {{ app_version }}
        </q-tooltip>
      </div>
    </div>
  </q-drawer>

  <div v-if="shouldShowSidebar && !miniState" class="drawer-close">
    <q-btn
      dense
      round
      unelevated
      class="highlighted-back menu-close-button"
      icon="chevron_left"
      @click="miniState = true"
    />
  </div>

  <q-dialog v-model="showAppVersion" @escape-key="showAppVersion = false">
    <q-card class="small-popup-size">
      <VersionsList :app_version="app_version" />
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import logoutUtil from 'src/utils/cache';
import { defineComponent, ref, shallowRef } from 'vue';
import { SUPPORT_URL } from 'src/pages/APIs';
import type { dynamicObj } from 'src/pages/assets';
import { taskApiService } from 'src/services';
import { dark_mode_setting, CONSTANTS } from 'src/constants';
import VersionsList from 'src/components/LayoutHeader/VersionsList.vue';
import {
  useSettingStore,
  useTaskStore,
  useWebSocketStore,
  useUserStore,
} from 'src/store/main';
import { useSidebarPreferencesStore } from 'src/store/sidebar-preferences.store';
import {
  getUserDetailFromkey,
  getUserDetails,
  isUserAdmin,
  isSupplierAdmin,
  isSupplierUser,
} from 'src/utils/UserDetails';
import {
  open_search_enabled,
  asn_dashboard_setting,
  workflow_builder_setting,
  invoice_dashboard_setting,
  supplier_dashboard_setting,
  report_setting,
  tasks_notification_setting,
  analytics_dashboard_setting,
} from 'src/constants';
import cache from 'src/utils/cache';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { canAccessAnalytics } from 'src/utils/analytics-access';
import { useUserIdentityVersion } from 'src/utils/user-identity';
import { shouldShowWorkflowMenu } from 'src/components/LayoutHeader/sideMenuModuleVisibility';
import { paths } from 'src/router/paths';

// NavIcon for Iconify-based navigation icons; docOperatorIcon kept as custom SVG (brand icon)
import NavIcon from 'src/components/icons/NavIcon.vue';
import { VueDraggableNext as draggable } from 'vue-draggable-next';
import docOperatorIcon from 'src/pages/Invoice/components/doc_operator_icon.vue';
import InvoiceIcon from 'src/pages/Invoice/components/invoice-icon.vue';
import UserDropDown from 'src/components/LayoutHeader/AccountDropdown/UserDropDown.vue';

export default defineComponent({
  name: 'MainLayout',
  mixins: [cache],
  props: {
    is_supplier: {
      type: Boolean,
      default: false,
    },
  },
  components: {
    NavIcon,
    UserDropDown,
    VersionsList,
    docOperatorIcon,
    draggable,
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    this.unsubscribeToChannel('all_open_task_count');
    next();
  },
  watch: {
    userIdentityVersion() {
      this.analyticsAllowedRoleIds = [];
      this.analyticsUserRoleIds = [];
      this.prepareMenuItems();
      void this.loadAnalyticsRoleAccess();
    },
    user_settings: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.prepareMenuItems();
      },
    },
    websocketHasError: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.use_websocket = false;
          this.handleWebsocketDelay();
        }
      },
    },
    all_tasks_count_data_flag: {
      handler: function (newVal, oldVal) {
        if (newVal == false) {
          return;
        }
        this.data_status = 'received';
        this.handleWebSocketResult(this.all_tasks_count);
      },
    },
  },
  mounted: async function () {
    await this.init();

    document.addEventListener('keydown', this.keyDownEvent);
    document.addEventListener('refresh_view', this.getTaskCountListener);
  },
  unmounted() {
    document.removeEventListener('keydown', this.keyDownEvent);
    document.removeEventListener('refresh_view', this.getTaskCountListener);
  },
  methods: {
    async init() {
      await this.startSettingsFetch();
      if (!this.user_settings || Object.keys(this.user_settings).length == 0) {
        return;
      }
      this.getUserDetailByKey();
      this.prepareMenuItems();

      // DOCB-14282: the analytics icon needs the org's role grants and the
      // user's own roles, and this call is deliberately NOT awaited.
      //
      // It used to be, right here, and that broke the WebSocket critical test
      // (platform/websocket-integration.spec.ts Test 1): everything after this
      // point in init() — including handleTasks(), which brings the socket up —
      // sat behind two fresh network round trips. Blocking app startup on a
      // menu-icon decision is the wrong trade in any case; the icon is not
      // worth delaying the socket, the task counts, or anything else here.
      //
      // So the menu renders immediately without the grants (org admins are
      // already correct, since the gate short-circuits on admin) and rebuilds
      // once they land. A non-admin who was granted the tab sees the icon
      // appear a moment later rather than the whole app starting later.
      void this.loadAnalyticsRoleAccess();

      if (process.env.APP_VUE_CURRENT_VERSION) {
        this.app_version =
          process.env.APP_VUE_CURRENT_VERSION.toString() || '0.0.0';
      }

      // this.subscribeToChannel('all_open_task_count');
      this.handleTasks();
      this.drawer = !this.isMobile();
    },
    isMobile() {
      if (
        /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
          navigator.userAgent,
        )
      ) {
        return true;
      } else {
        return false;
      }
    },
    isActive(route: string) {
      if (!route) return false;
      const currentPath = this.$route.path;
      const targetPath = route.split('?')[0];
      return currentPath === targetPath;
    },
    getUserDetailByKey() {
      let organisationsFromStorage = getUserDetailFromkey('organisations');
      let FirstIndexOfOrganisations = organisationsFromStorage[0] as any;
      if (!FirstIndexOfOrganisations) {
        return;
      }
      if (FirstIndexOfOrganisations.status === 'pending_ap_approval') {
        this.supplier_approval_status = 'pending_approval';
      } else {
        this.supplier_approval_status = FirstIndexOfOrganisations.status;
      }
    },
    prepareMenuItems() {
      this.menuList = [];

      //if user is supplier admin and supplier is approved then hide the document dashboard redirect to invoice dashboard
      if (
        (isSupplierAdmin() && this.supplier_approval_status !== 'approved') ||
        !isSupplierUser()
      ) {
        this.menuList = [
          {
            label: 'dashboard',
            name: 'document_dashboard',
            icon: 'mdi:view-dashboard',
            separator: false,
            to: '/dashboard',
          },
        ];
      }
      this.bottomItems = [
        // Sitemap (quick-search index) is hidden for supplier users — it
        // exposes admin/internal routes that aren't relevant to them.
        ...(!isSupplierUser()
          ? [
              {
                label: 'sitemap',
                name: 'sitemap',
                icon: 'mdi:magnify',
                separator: false,
                to: '/sitemap',
              },
            ]
          : []),
        {
          label: 'support',
          name: 'support',
          icon: 'mdi:lifebuoy',
          separator: false,
          to: '/support',
        },
        {
          label: 'idea_board',
          name: 'ideas',
          icon: 'mdi:lightbulb-on-outline',
          separator: false,
          to: '/ideas',
        },
        {
          label: 'user',
          name: 'user',
          icon: 'mdi:account-circle',
          separator: false,
          to: '',
        },
      ];

      if (isSupplierUser()) {
        const firstOrg: any = getUserDetailFromkey('organisations')[0];
        if (firstOrg.status === 'approved') {
          this.bottomItems.splice(0, 0, {
            label: 'settings',
            name: 'settings',
            icon: 'mdi:cog',
            separator: true,
            to: '/setting',
          });
        }
      } else {
        this.bottomItems.splice(0, 0, {
          label: 'settings',
          name: 'settings',
          icon: 'mdi:cog',
          separator: true,
          to: '/setting',
        });
      }

      this.handleOpenSearch();
      this.handleTaskAndNotification();
      this.handleAsnDashbaordMenu();
      this.handleReportMenu();
      this.handleWorkflowMenu();
      this.handleSupplierWorkflowMenu();
      this.handlePurchaseOrderMenu();
      this.handleInvoiceDashboardMenu();
      this.handleShipmentOrderMenu();
      this.handleDocOperatorMenu();
      this.handleSupplierStatisticsMenu();
      this.handleDocnetMenu();
      this.handleOpenSearch();
      // 2026-05-05: Knowledge Graph icon hidden from sidebar.
      // Feature is still under active development — UX, performance,
      // and edge cases (empty graph, large graph load times) need work
      // before exposing to customers. The route /graph-explorer stays
      // accessible for internal development/testing; only the sidebar
      // entry is suppressed. Re-enable by uncommenting this line.
      // this.handleGraphExplorerMenu();
      this.handleAnalyticsDashboardMenu();

      if (this.is_supplier) {
        return;
      }

      this.menuAccessibleCheck();

      // Apply user sidebar preferences (custom order and visibility)
      if (this.sidebarPrefs.hasCustomPreferences) {
        this.menuList = this.sidebarPrefs.applyPreferences(this.menuList);
      }
    },
    handleAsnDashbaordMenu() {
      if (!this.user_settings[this.asn_dashboard_setting]) {
        this.user_settings[this.asn_dashboard_setting] = false;
      }
      const isAsnDasboardEnabled = toBoolPreference(
        this.user_settings[this.asn_dashboard_setting],
      );
      const menuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'asn_dashboard',
      );
      if (menuIndex === -1 && isAsnDasboardEnabled) {
        if (!isSupplierUser()) {
          this.menuList.push({
            label: 'advance_shipment_dashboard',
            name: 'asn_dashboard',
            icon: 'mdi:truck-delivery-outline',
            separator: false,
            to: this.paths.shipments.asn(),
          });
        }
      } else if (!isAsnDasboardEnabled && menuIndex !== -1) {
        this.menuList.splice(menuIndex, 1);
      }
    },
    handleTaskAndNotification() {
      if (!this.user_settings[this.tasks_notification_setting]) {
        this.user_settings[this.tasks_notification_setting] = false;
      }
      const isTaskEnabled = toBoolPreference(
        this.user_settings[this.tasks_notification_setting],
      );
      const menuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'tasks',
      );
      if (menuIndex === -1 && isTaskEnabled) {
        if (!isSupplierUser()) {
          this.menuList.push({
            label: 'tasks',
            name: 'tasks',
            icon: 'mdi:clipboard-check-outline',
            separator: false,
            to: this.paths.tasks.list(),
          });
        }
        return;
      }

      if (!isTaskEnabled && menuIndex !== -1) {
        this.menuList.splice(menuIndex, 1);
      }
    },
    handleSupplierWorkflowMenu() {
      // Find the 'supplier_dashboard' menu item index, if it exists
      let foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'supplier_dashboard',
      );
      const isSupplierDashboardNeeded = toBoolPreference(
        this.user_settings[this.supplier_dashboard_setting],
      );

      if (isSupplierDashboardNeeded && foundMenuIndex === -1) {
        if (!isSupplierUser()) {
          this.menuList.push({
            label: 'supplier_management',
            name: 'supplier_dashboard',
            icon: 'mdi:account-group',
            separator: false,
            to: '/supplier/dashboard',
          });
        }
      } else if (!isSupplierDashboardNeeded && foundMenuIndex !== -1) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handleWorkflowMenu() {
      const shouldShow = shouldShowWorkflowMenu(
        this.user_settings[this.workflow_builder_setting],
        { isSupplier: isSupplierUser(), isAdmin: isUserAdmin() },
      );
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'workflows',
      );
      if (shouldShow && foundMenuIndex === -1) {
        this.menuList.push({
          label: 'workflows',
          name: 'workflows',
          icon: 'mdi:sitemap-outline',
          separator: false,
          to: this.paths.workflows.dashboard(),
        });
      } else if (!shouldShow && foundMenuIndex !== -1) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handlePurchaseOrderMenu() {
      if (!this.user_settings[this.po_dashboard]) {
        this.user_settings[this.po_dashboard] = false;
      }
      const isPoEnabled = toBoolPreference(
        this.user_settings[this.po_dashboard],
      );
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.label === 'purchase_order',
      );
      if (foundMenuIndex === -1 && isPoEnabled) {
        if (isSupplierUser() || isSupplierAdmin()) {
          if (this.supplier_approval_status == 'approved') {
            this.menuList.push({
              label: 'purchase_order',
              name: 'purchase_orders_and_invoices',
              icon: 'mdi:cart-outline',
              separator: false,
              to: this.paths.supplier.purchaseOrders(),
            });
          }
        } else {
          this.menuList.push({
            label: 'purchase_order',
            name: 'purchase_orders_and_invoices',
            icon: 'mdi:cart-outline',
            separator: false,
            to: this.paths.supplier.purchaseOrders(),
          });
        }
      } else if (foundMenuIndex !== -1 && !isPoEnabled) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handleReportMenu() {
      if (!this.user_settings[this.report_setting]) {
        this.user_settings[this.report_setting] = false;
      }
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'report',
      );
      const isLayoutReportDashboardNeeded = toBoolPreference(
        this.user_settings[this.report_setting],
      );

      if (isLayoutReportDashboardNeeded && foundMenuIndex === -1) {
        this.menuList.push({
          label: 'report',
          name: 'report',
          icon: 'mdi:chart-bar',
          separator: false,
          to: this.paths.analytics.reports(),
        });
      } else if (!isLayoutReportDashboardNeeded && foundMenuIndex !== -1) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },
    async loadAnalyticsRoleAccess() {
      try {
        // Imported lazily on purpose. Both of these reach the services barrel,
        // which instantiates 30+ services and pulls the generated SDK (and its
        // axios instance) in at module load. Static imports here would drag
        // all of that into the side menu's chunk — the exact barrel-import
        // problem the repo guidance calls out — and would break every spec
        // that mounts SideMenu with a partially mocked `pages/APIs`.
        const [{ loadAnalyticsAccess }, { Acl }] = await Promise.all([
          import('src/composables/useAnalyticsAccess'),
          import('src/core/acls/index'),
        ]);
        const [allowed] = await Promise.all([
          loadAnalyticsAccess(),
          Acl.fetchUserGroups(),
        ]);
        this.analyticsAllowedRoleIds = allowed;
        this.analyticsUserRoleIds = Acl._getUserGroupIds();
      } catch {
        // Fail closed: no grants means admins only, which is the safe default
        // and the state every org starts in.
        this.analyticsAllowedRoleIds = [];
        this.analyticsUserRoleIds = [];
      }
      // Rebuild now that the grants are known — this runs after init() has
      // already drawn the menu, so it is what makes the icon appear for a
      // granted non-admin.
      this.prepareMenuItems();
    },

    handleAnalyticsDashboardMenu() {
      // DOCB-14282: the icon follows the shared gate, not a local admin check
      // — org admins always, plus any role an admin granted the tab to on
      // Settings -> Roles. `canAccessAnalytics` is the same function the page,
      // the Touchless composable and the route guard call, so the icon and
      // the page can no longer disagree.
      const canSee = canAccessAnalytics({
        userSettings: this.user_settings,
        isAdmin: isUserAdmin(),
        userRoleIds: this.analyticsUserRoleIds,
        allowedRoleIds: this.analyticsAllowedRoleIds,
      });
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'analytics_dashboard',
      );
      if (canSee && foundMenuIndex === -1) {
        this.menuList.splice(1, 0, {
          label: 'analytics_dashboard',
          name: 'analytics_dashboard',
          icon: 'mdi:chart-line',
          separator: false,
          to: this.paths.analytics.dashboard(),
        });
      } else if (!canSee && foundMenuIndex !== -1) {
        // Access revoked mid-session (module switched off, or the role's grant
        // withdrawn) — drop the icon instead of leaving a dead link.
        this.menuList.splice(foundMenuIndex, 1);
      }
    },
    handleInvoiceDashboardMenu() {
      const isInvoiceEnabled = toBoolPreference(
        this.user_settings[this.invoice_dashboard_setting],
      );
      const menuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'invoice_dashboard',
      );
      if (menuIndex === -1 && isInvoiceEnabled) {
        if (isSupplierUser() || isSupplierAdmin()) {
          if (this.supplier_approval_status == 'approved') {
            this.menuList.push({
              label: 'invoice_dashboard',
              name: 'invoice_dashboard',
              icon: InvoiceIcon,
              separator: false,
              to: this.paths.invoices.dashboard(),
            });
          }
        } else {
          this.menuList.push({
            label: 'invoice_dashboard',
            name: 'invoice_dashboard',
            icon: InvoiceIcon,
            separator: false,
            to: this.paths.invoices.dashboard(),
          });
        }
      } else if (!isInvoiceEnabled && menuIndex !== -1) {
        this.menuList.splice(menuIndex, 1);
      }
    },

    handleShipmentOrderMenu() {
      if (!this.user_settings[CONSTANTS.shipment_order_dashboard]) {
        this.user_settings[CONSTANTS.shipment_order_dashboard] = false;
      }

      const isShipmentOrderEnabled = toBoolPreference(
        this.user_settings[CONSTANTS.shipment_order_dashboard],
      );
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.label === 'shipment_order',
      );
      if (foundMenuIndex === -1 && isShipmentOrderEnabled) {
        if (!isSupplierUser()) {
          this.menuList.push({
            label: 'shipment_order',
            name: 'shipment_order',
            icon: 'mdi:cart-plus',
            separator: false,
            to: this.paths.shipments.orders(),
          });
        }
      } else if (foundMenuIndex !== -1 && !isShipmentOrderEnabled) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handleDocOperatorMenu() {
      if (!this.user_settings[CONSTANTS.doc_operator_setting]) {
        this.user_settings[CONSTANTS.doc_operator_setting] = false;
      }

      const isOperatorEnabled = toBoolPreference(
        this.user_settings[CONSTANTS.doc_operator_setting],
      );
