            to: '/doc-operator',
          });
        }
      } else if (foundMenuIndex !== -1 && !isOperatorEnabled) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handleDocnetMenu() {
      const isDocnetEnabled = toBoolPreference(
        this.user_settings[CONSTANTS.docnet_setting],
      );
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.label === 'docnet',
      );
      if (isDocnetEnabled && !isSupplierUser()) {
        if (foundMenuIndex === -1) {
          this.menuList.push({
            label: 'docnet',
            name: 'docnet',
            icon: 'mdi:lan',
            separator: false,
            to: '/doc-net',
          });
        }
      } else if (foundMenuIndex !== -1 && !isDocnetEnabled) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handleSupplierStatisticsMenu() {
      // Supplier Statistics page visibility
      if (!this.user_settings[CONSTANTS.supplier_statistics_setting]) {
        this.user_settings[CONSTANTS.supplier_statistics_setting] = false;
      }
      const isSupplierStatisticsEnabled = toBoolPreference(
        this.user_settings[CONSTANTS.supplier_statistics_setting],
      );
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'supplier_statistics',
      );
      if (isSupplierStatisticsEnabled && foundMenuIndex === -1) {
        if (!isSupplierUser()) {
          this.menuList.push({
            label: 'supplier_statistics',
            name: 'supplier_statistics',
            icon: 'mdi:chart-bar',
            separator: false,
            to: this.paths.analytics.suppliers(),
          });
        }
      } else if (!isSupplierStatisticsEnabled && foundMenuIndex !== -1) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handleOpenSearch() {
      const isOpenSearchEnabled = toBoolPreference(
        this.user_settings[this.open_search_enabled],
      );
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'open_search',
      );
      if (isOpenSearchEnabled && foundMenuIndex === -1) {
        // Open search is hidden for supplier users (same as the knowledge graph).
        if (!isSupplierUser()) {
          this.menuList.push({
            label: 'open_search',
            name: 'open_search',
            icon: 'mdi:file-search-outline',
            separator: false,
            to: this.paths.search(),
          });
        }
      } else if (!isOpenSearchEnabled && foundMenuIndex !== -1) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    handleGraphExplorerMenu() {
      const isOpenSearchEnabled = toBoolPreference(
        this.user_settings[this.open_search_enabled],
      );
      const foundMenuIndex = this.menuList.findIndex(
        (item: any) => item.name === 'graph_explorer',
      );
      if (isOpenSearchEnabled && foundMenuIndex === -1) {
        if (!isSupplierUser()) {
          this.menuList.push({
            label: 'knowledge_graph',
            name: 'graph_explorer',
            icon: 'mdi:graph-outline',
            separator: false,
            to: this.paths.analytics.graphExplorer(),
          });
        }
      } else if (!isOpenSearchEnabled && foundMenuIndex !== -1) {
        this.menuList.splice(foundMenuIndex, 1);
      }
    },

    // ─── Sidebar Customization Methods ───
    enterEditMode() {
      // Import defaults if no preferences exist yet
      if (!this.sidebarPrefs.hasCustomPreferences) {
        this.sidebarPrefs.importDefaults(this.menuList);
      }
      // Build edit list: all items from preferences (including hidden ones)
      this.editMenuList = this.buildEditList();
      this.sidebarEditMode = true;
    },

    exitEditMode() {
      this.sidebarEditMode = false;
      this.prepareMenuItems();
    },

    onDragEnd() {
      this.sidebarPrefs.reorder(this.editMenuList.map((i: any) => i.name));
    },

    buildEditList(): any[] {
      // Rebuild the full menu from feature flags WITHOUT applying preferences
      // so hidden items are included in the edit view
      const savedPrefs = this.sidebarPrefs.preferences;
      const savedMenuList = this.menuList;

      // Temporarily clear preferences and rebuild to get ALL items
      this.sidebarPrefs.preferences = [];
      this.prepareMenuItems();
      const allItems = [...this.menuList];

      // Restore preferences and menu
      this.sidebarPrefs.preferences = savedPrefs;
      this.menuList = savedMenuList;

      // Sort by saved preference order, append new items at end
      const sorted: any[] = [];
      const remaining = [...allItems];

      if (savedPrefs.length > 0) {
        const orderedPrefs = [...savedPrefs].sort((a, b) => a.order - b.order);
        for (const pref of orderedPrefs) {
          const idx = remaining.findIndex(
            (item: any) => item.name === pref.itemId,
          );
          if (idx !== -1) {
            sorted.push(remaining[idx]);
            remaining.splice(idx, 1);
          }
        }
      }
      sorted.push(...remaining);

      // Decorate with visibility state
      return sorted.map((item: any) => {
        const pref = savedPrefs.find((p) => p.itemId === item.name);
        return {
          ...item,
          _visible: pref ? pref.visible : true,
          _pinned: pref ? pref.pinned : false,
        };
      });
    },

    toggleItemVisibility(itemName: string) {
      this.sidebarPrefs.toggleVisibility(itemName);
      this.editMenuList = this.buildEditList();
    },

    moveItemUp(index: number) {
      if (index <= 0) return;
      const items = [...this.editMenuList];
      const temp = items[index];
      items[index] = items[index - 1];
      items[index - 1] = temp;
      this.editMenuList = items;
      this.sidebarPrefs.reorder(items.map((i: any) => i.name));
    },

    moveItemDown(index: number) {
      if (index >= this.editMenuList.length - 1) return;
      const items = [...this.editMenuList];
      const temp = items[index];
      items[index] = items[index + 1];
      items[index + 1] = temp;
      this.editMenuList = items;
      this.sidebarPrefs.reorder(items.map((i: any) => i.name));
    },

    resetSidebarPreferences() {
      this.sidebarPrefs.resetToDefaults();
      this.sidebarEditMode = false;
      this.prepareMenuItems();
    },

    isDashboardRoute() {
      return (
        this.$route.fullPath == '/dashboard' ||
        this.$route.fullPath == '/supplier/dashboard'
      );
    },

    shouldShowSidebar() {
      const settingsRoutes = ['/setting', '/settings'];
      return (
        this.isDashboardRoute() ||
        this.$route.fullPath === '/sitemap' ||
        settingsRoutes.some((route) => this.$route.fullPath.startsWith(route))
      );
    },

    keyDownEvent(e: any) {
      /*if (e.keyCode === 68 && e.shiftKey) {
        this.miniState = !this.miniState;
      }*/
    },
    navigateTo(route: string) {
      if (!route) return;

      this.$router.push(route);
    },
    menuAccessibleCheck() {
      // Hide the workflow, report, purchase order menu for supplier users and supplier dashboard for supplier user
      if (isSupplierUser()) {
        const hideMenus = [
          'workflow',
          'report',
          'supplier_dashboard',
          'asn_dashboard',
        ];
        const firstOrg: any = getUserDetailFromkey('organisations')[0];
        if (firstOrg.status !== 'approved') {
          hideMenus.push('purchase_orders_and_invoices');
        }
        const newMenulist = this.menuList.filter((item: any) => {
          if (hideMenus.indexOf(item.name) != -1) {
            return false;
          }
          return true;
        });
        this.menuList = newMenulist;
      }
    },

    async handleTasks() {
      // There is possibility of any filters there and it will effect count
      document.addEventListener('refreshTasks', this.getTaskCountListener);

      // Add error handling for initial task count
      try {
        await this.getTaskCount();
      } catch (error) {
        console.warn('Initial task count failed, will retry later:', error);
      }

      // Reduce frequency from 2min to 5min and add error handling
      setInterval(() => {
        this.getTaskCount().catch((error: any) => {
          console.warn('Periodic task count failed:', error);
        });
      }, 300000); // 5 minutes instead of 2 minutes
    },

    terminateLongRunningTask(promise: any, ms: number) {
      return new Promise((resolve, reject) => {
        // Increase timeout from 60s to 120s for better reliability
        const timer = setTimeout(() => {
          console.warn('Task count operation timed out after', ms, 'ms');
          reject(new Error('Operation timed out'));
          this.handleWebsocketDelay();
        }, ms);

        promise
          .then((result: any) => {
            clearTimeout(timer);
            resolve(result);
          })
          .catch((err: any) => {
            clearTimeout(timer);
            console.warn('Task count promise rejected:', err);
            reject(err);
            this.handleWebsocketDelay();
          });
      });
    },

    async getTaskCount() {
      const { CACHE_TN } = this.user_settings;
      const params: dynamicObj = {
        cache: false,
        ttl: 0,
      };

      if (CACHE_TN) {
        let cache = JSON.parse(CACHE_TN);
        params['cache'] = cache.enabled;
        params['ttl'] = cache.ttl;
      }

      const org_id = this.getOrgId();
      if (org_id) {
        params['org_id'] = org_id;
      }

      // DOCB-10122: use the user's own sub-org context. getSubOrgId() prefers
      // the currently open document's sub_org_id, which silently re-scoped the
      // periodic (5-min) count refresh to that document's sub-org and made the
      // badge drop from the real org-wide count to the sub-org-filtered one.
      const sub_org_id = await this.getUserSubOrgId();
      if (sub_org_id && sub_org_id != this.getOrgId()) {
        params['sub_org_id'] = sub_org_id;
      }

      if (this.use_websocket) {
        try {
          // Increase WebSocket timeout to 120 seconds for better reliability
          await this.terminateLongRunningTask(
            this.getTaskCountByWebSocket(params),
            120000,
          );
        } catch (error) {
          console.warn(
            'WebSocket task count failed, falling back to HTTP:',
            error,
          );
          this.use_websocket = false;
          await this.getTaskCountByHttpCall(params);
        }
        return;
      }

      if (this.wsConnectTry > 0) {
        console.warn(
          'Skipping task count due to ongoing WebSocket connection attempts',
        );
        return;
      }

      // Add error handling for HTTP calls
      try {
        await this.getTaskCountByHttpCall(params);
      } catch (error) {
        console.warn('HTTP task count failed:', error);
      }
    },

    async getTaskCountByWebSocket(params: any) {
      try {
        this.data_status = 'fetching';
        this.all_tasks_count_data_flag = false;
        const response = await this.sendMessageToSocket(
          'all_open_task_count',
          params,
        );

        if (!response || !response.hasOwnProperty('data')) {
          throw 'Error in getting task count';
        }
        this.setOpenTaskCount(response.data);
      } catch (err) {
        this.handleWebsocketDelay();
      }
    },

    async getTaskCountByHttpCall(params: any) {
      try {
        const response = await taskApiService.getTotalTaskCount(params);
        if (
          response &&
          response.hasOwnProperty('success') &&
          response.success
        ) {
          this.setOpenTaskCount(response.data);
        }
      } catch (error) {
        logError('Error in getting task count', error);
      }
    },

    getTaskCountListener() {
      this.getTaskCount();
    },

    logout() {
      logoutUtil.methods.logout();
    },
    handleWebsocketDelay() {
      // websocket is still fetching data and we are not getting any response
      if (this.data_status === 'received') {
        return;
      }
      logInfo('turning off websocket and switching to https', this.data_status);

      this.use_websocket = false;
      this.getTaskCount();
      this.wsConnectTry++;
      setTimeout(this.turnOnWebSocket, 5000);
    },
    turnOnWebSocket() {
      if (this.websocketHasError) {
        return;
      }

      this.use_websocket = true;
    },
    handleWebSocketResult(response: any) {
      if (!response) {
        return;
      }
      this.use_websocket = true;
      this.setOpenTaskCount(response.data);
    },
  },
  data() {
    return {
      wsConnectTry: ref(0),
      use_websocket: ref(true),
      showAppVersion: ref(false),
      showIcons: false,
      supportURL: SUPPORT_URL,
      dark_mode_setting,
      menuList: shallowRef([] as any),
      bottomItems: shallowRef([] as any),
      supplier_dashboard_setting,
      asn_dashboard_setting,
      tasks_notification_setting,
      workflow_builder_setting,
      report_setting,
      po_dashboard: CONSTANTS.po_dashboard,
      invoice_dashboard_setting,
      open_search_enabled,
      showUserMenu: false,
      analytics_dashboard_setting,
      // DOCB-14282: the roles allowed to see the Analytics Dashboard tab, and
      // the roles this user is in. Both fetched once in init(); empty means
      // admins only, which is also the correct answer while the requests are
      // still in flight.
      analyticsAllowedRoleIds: [] as string[],
      analyticsUserRoleIds: [] as string[],
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, drawer, loading_settings } =
      storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;

    const user_store = useUserStore();
    const { getUserSubOrgId, getOrgId } = user_store;

    const task_store = useTaskStore();
    const { total_records, open_task_count } = storeToRefs(task_store);
    const { getTasks, setOpenTaskCount } = task_store;
    const supplier_approval_status = ref('');

    const sidebarPrefs = useSidebarPreferencesStore();
    sidebarPrefs.initialize();

    const websocket_store = useWebSocketStore();
    const {
      all_tasks_count,
      isConnected,
      hasError: websocketHasError,
      all_tasks_count_data_flag,
    } = storeToRefs(websocket_store);
    const {
      subscribeToChannel,
      unsubscribeToChannel,
      sendMessageByType: sendMessageToSocket,
    } = websocket_store;

    return {
      paths,
      userIdentityVersion: useUserIdentityVersion(),
      drawer,
      isConnected,
      user_settings,
      total_records,
      open_task_count,
      all_tasks_count,
      loading_settings,
      websocketHasError,
      supplier_approval_status,
      all_tasks_count_data_flag,
      miniState: ref(true),
      setOpenTaskCount,
      data_status: ref(''),
      app_version: ref('0.0.0'),

      sidebarPrefs,
      sidebarEditMode: ref(false),
      editMenuList: shallowRef([] as any),

      getTasks,
      getOrgId,
      getUserSubOrgId,
      startSettingsFetch,
      subscribeToChannel,
      sendMessageToSocket,
      unsubscribeToChannel,
    };
  },
});
</script>

