<!--vbase-->
<template>
  <label for="Font Size">{{ $t('font_size') }}</label>

  <template v-for="(font, index) in font_size_options" :key="index">
    <q-radio
      v-model="font_size"
      :val="font.value"
      @update:model-value="fontSizeUpdated()"
      :label="$t(font.label)"
    />
  </template>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useUserFontSizeStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  el: '#app',
  mixins: [],
  props: {},
  components: {},
  data() {
    return {};
  },
  mounted: function () {
    this.init();
  },
  methods: {
    async init() {
      await this.initFontSize();
    },

    fontSizeUpdated() {
      this.setAppFontSize();
      this.saveFontSizeValue();
    },
  },
  setup() {
    const user_font_size_store = useUserFontSizeStore();
    const { saveFontSizeValue, initFontSize, setAppFontSize } =
      user_font_size_store;
    const { font_size, font_size_options } = storeToRefs(user_font_size_store);

    return {
      font_size,
      font_size_options,
      saveFontSizeValue,
      initFontSize,
      setAppFontSize,
    };
  },
});
</script>
