import { paths } from 'src/router/paths';

/**
 * Key for MainLayout's <router-view>. Most routes key on fullPath, so a query
 * change remounts the page. /settings, /workflows and /analytics own their
 * in-page navigation (sub-paths / `?tab=`), so they key on a stable string to
 * avoid remounting (and the visible reload flash) on every such change.
 */
export function resolveRouteLayoutKey(path: string, fullPath: string): string {
  if (path.startsWith('/settings')) return 'settings-layout';
  if (path === paths.workflows.dashboard()) return 'workflows';
  // Owns `?tab=` for its flow-type tabs and the Touchless report (DOCB-14197).
  // Without this, every tab click remounts a 3771-line page — and re-runs its
  // whole data load.
  if (path === paths.analytics.dashboard()) return 'analytics';
  return fullPath;
}
