/**
 * Groups slow calls by their `type` classifier and computes per-group
 * count / avg / p95 duration. Sorted by p95 descending so the worst
 * offenders surface first in the Performance Dialog and in the support
 * ticket HTML body.
 */

import type { SlowCall } from 'src/utils/performanceStore';

export interface SlowCallsByTypeRow {
  type: string;
  count: number;
  avgMs: number;
  p95Ms: number;
}

export function computeSlowCallsByType(calls: Pick<SlowCall, 'type' | 'duration'>[]): SlowCallsByTypeRow[] {
  const groups = new Map<string, number[]>();
  for (const call of calls) {
    const existing = groups.get(call.type) ?? [];
    existing.push(call.duration);
    groups.set(call.type, existing);
  }
  const rows: SlowCallsByTypeRow[] = [];
  for (const [type, durations] of groups.entries()) {
    durations.sort((a, b) => a - b);
    // Nearest-rank p95 (0-indexed): ceil(n * 0.95) - 1. The previous
    // Math.floor(n * 0.95) returned a rank one too high whenever n*0.95 is an
    // integer (every n divisible by 20), reporting the maximum as the "p95".
    const p95Index = Math.min(
      durations.length - 1,
      Math.max(0, Math.ceil(durations.length * 0.95) - 1),
    );
    rows.push({
      type,
      count: durations.length,
      p95Ms: durations[p95Index]!,
      avgMs: Math.round(durations.reduce((a, b) => a + b, 0) / durations.length),
    });
  }
  rows.sort((a, b) => b.p95Ms - a.p95Ms);
  return rows;
}
