<template>
  <q-card style="max-width: 60vw" id="edit-user-popup">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{ $t('user_edit') }}</span>
      </q-toolbar-title>
      <q-btn
        flat
        round
        dense
        icon="close"
        v-close-popup
        @click="$emit('popClosed')"
      />
    </q-toolbar>
    <form autocomplete="off">
      <!-- Default-Org (M3, SD 2860679170 §4.3): only meaningful with >1 org
           membership — a single-org user has nothing to default between. -->
      <q-card-section v-if="organisations.length > 1" data-test="default-org-section">
        <div class="text-subtitle2 q-mb-sm">{{ $t('default_org_section_title') }}</div>
        <p class="text-caption text-muted-foreground q-mb-sm">{{ $t('default_org_section_hint') }}</p>
        <q-input
          v-if="showOrgSearch"
          v-model="orgSearch"
          outlined
          dense
          clearable
          color="primary"
          class="q-mb-sm"
          data-test="default-org-search"
          :label="$t('org_picker_search_placeholder')"
        >
          <template #append>
            <q-icon name="search" />
          </template>
        </q-input>
        <q-list bordered class="default-org-list">
          <q-item
            v-for="org in filteredOrganisations"
            :key="org.org_id"
            clickable
            v-ripple
            tag="label"
            :data-test="'default-org-item-' + org.org_id"
          >
            <q-item-section avatar>
              <q-radio v-model="selectedDefaultOrgId" :val="org.org_id" color="primary" />
            </q-item-section>
            <q-item-section>{{ org.name }}</q-item-section>
            <q-item-section side>
              <q-badge v-if="org.region" outline color="primary">{{ org.region.toUpperCase() }}</q-badge>
            </q-item-section>
          </q-item>
        </q-list>
        <div
          v-if="showOrgSearch && !filteredOrganisations.length"
          class="text-caption text-muted-foreground q-mt-sm"
          data-test="default-org-no-results"
        >
          {{ $t('org_picker_search_no_results') }}
        </div>
        <div
          v-if="hiddenDefaultOrgName"
          class="text-caption text-muted-foreground q-mt-sm"
          data-test="default-org-hidden-selection"
        >
          {{ $t('org_picker_selection_hidden', { name: hiddenDefaultOrgName }) }}
        </div>
        <div class="row justify-end q-mt-sm">
          <f-btn
            :label="$t('save')"
            :disable="!selectedDefaultOrgId || selectedDefaultOrgId === currentDefaultOrgId || savingDefaultOrg"
            data-test="default-org-save-button"
            @click="saveDefaultOrg"
          />
        </div>
      </q-card-section>
      <q-separator v-if="organisations.length > 1" />

      <q-card-section>
        <div class="row">
          <div class="column q-gutter-y-md">
            <div class="row justify-evenly">
              <DateFormat class="col q-mr-xs" />
              <AmountFormat class="col q-ml-xs" />
            </div>

            <div class="row items-center q-gutter-sm">
              <fontSizeOption />
            </div>

            <!-- <div>
            <darkModeOption />
        </div> -->

            <DualMonitor />

            <div class="row items-center text-weight-medium q-gutter-x-sm">
              <q-btn
                style="padding: 4px 6px"
                flat
                color="primary"
                @click="$emit('refreshClicked')"
                icon="refresh"
                class="no-padding-left-right"
              />
              <span>{{ $t('refresh_user_settings') }}</span>
            </div>
          </div>

          <q-separator vertical inset class="q-mx-md" />

          <div
            class="row text-red-5"
            style="
              flex-direction: column;
              width: 100%;
              font-size: 1.2rem;
              font-weight: bold;
            "
            v-if="api_errors !== ''"
          >
            Error: {{ api_errors }}
          </div>
          <div class="column items-center">
            <q-input
              dense
              outlined
              :class="'full-width cursor-pointer first_name'"
              v-model="model['first_name']"
              :label="$t('first_name')"
              :error-message="model_error['first_name']"
              :error="model_error['first_name'] != ''"
            >
            </q-input>

            <q-input
              dense
              outlined
              :label="$t('last_name')"
              :class="'full-width cursor-pointer last_name'"
              v-model="model['last_name']"
              :error-message="model_error['last_name']"
              :error="model_error['last_name'] != ''"
            >
            </q-input>

            <q-input
              v-if="!isPasswordEmpty()"
              dense
              outlined
              :class="'full-width cursor-pointer current_password'"
              v-model="model['current_password']"
              :label="$t('current_password')"
              :error-message="model_error['current_password']"
              :error="model_error['current_password'] != ''"
              :type="show_current_password === false ? 'password' : 'text'"
              data-test="current-password-input"
              autocomplete="current-password"
            >
              <template v-slot:append>
                <q-icon
                  :name="
                    show_current_password === false
                      ? 'visibility'
                      : 'visibility_off'
                  "
                  @click="show_current_password = !show_current_password"
                />
              </template>
            </q-input>

            <q-input
              dense
              outlined
              :class="'full-width cursor-pointer password'"
              v-model="model['password']"
              :label="$t('password')"
              :error-message="model_error['password']"
              :error="model_error['password'] != ''"
              :type="show_password === false ? 'password' : 'text'"
              data-test="password-input"
            >
              <template v-slot:append>
                <q-icon
                  :name="
                    show_password === false ? 'visibility' : 'visibility_off'
                  "
                  @click="show_password = !show_password"
                />
              </template>
              <template v-slot:after>
                <div class="cursor-pointer">
                  <q-icon name="info" color="primary" size="sm" />
                  <q-tooltip>{{ $t('password_hint') }}</q-tooltip>
                </div>
              </template>
            </q-input>

            <q-input
              dense
              outlined
              :class="[
                'full-width cursor-pointer confirm_password',
                model_error['password'] !== '' ? 'mt-30' : '',
              ]"
              v-model="model['confirm_password']"
              :error-message="model_error['confirm_password']"
              :label="$t('confirm_password')"
              :error="model_error['confirm_password'] != ''"
              :type="show_confirm_password === false ? 'password' : 'text'"
              data-test="confirm-password-input"
            >
              <template v-slot:append>
                <q-icon
                  :name="
                    show_confirm_password === false
                      ? 'visibility'
                      : 'visibility_off'
                  "
                  @click="show_confirm_password = !show_confirm_password"
                />
              </template>
            </q-input>
          </div>
        </div>
      </q-card-section>
      <q-separator />
      <q-card-section data-test="mfa-section">
        <div class="row items-center justify-between no-wrap">
          <div>
            <div class="text-weight-medium">{{ $t('mfa_settings_title') }}</div>
            <div class="text-caption text-grey-7">{{ $t('mfa_settings_intro') }}</div>
          </div>
          <q-btn
            outline
            color="primary"
            :label="$t('mfa_settings_manage')"
            data-test="mfa-manage-btn"
            @click="showMfaDialog = true"
          />
        </div>
      </q-card-section>
      <MfaSettings v-model="showMfaDialog" />
      <q-card-actions align="left" class="float-right q-ml-auto q-mr-sm">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          type="reset"
          v-close-popup
          @click="$emit('popClosed')"
        />
        <f-btn
          :label="$t('save')"
          class="q-ml-sm"
          @click="updateUserInfo"
          v-close-popup="saveClose"
        />
      </q-card-actions>
    </form>
  </q-card>

  <q-inner-loading
    :showing="processing"
    class="max-full-width full-height full-height-max"
  >
    <img class="loader" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import axios from 'axios';
import { storeToRefs } from 'pinia';
import { LocalStorage } from 'quasar';
import n8n_general from 'src/utils/n8n';
import { defineComponent, ref } from 'vue';
import { useUserStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { api, getAuthorizationToken } from 'pages/APIs';
import { notify } from 'src/components/notifications/notify';
import { specialChars, passwordPattern } from 'src/constants';
import DualMonitor from 'src/components/LayoutHeader/AccountDropdown/DualMonitor.vue';
import fontSizeOption from 'src/components/LayoutHeader/AccountDropdown/fontSizeOption.vue';
// import darkModeOption from 'src/components/LayoutHeader/AccountDropdown/darkModeOption.vue';
import DateFormat from 'src/components/LayoutHeader/AccountDropdown/DateFormat.vue';
import AmountFormat from 'src/components/LayoutHeader/AccountDropdown/AmountFormat.vue';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { getMe } from 'src/sdk/auth/me/me';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import type { MeOrganisationItem } from 'src/sdk/auth/models';
import MfaSettings from 'src/components/Settings/MfaSettings.vue';

// Kept in sync with OrgPicker.vue's SEARCH_THRESHOLD (DOCB-13836): both org
// lists get their filter at the same size, so users see one consistent rule.
const ORG_SEARCH_THRESHOLD = 8;

export default defineComponent({
  el: '#app',
  mixins: [n8n_general, helperMixin],
  data() {
    return {
      fields: [
        'first_name',
        'last_name',
        'password',
        'confirm_password',
        'current_password',
      ],
      empty_validation_fields: ['first_name', 'last_name'],
      // Default-Org (M3, SD §4.3)
      organisations: [] as MeOrganisationItem[],
      selectedDefaultOrgId: '' as string,
      currentDefaultOrgId: '' as string,
      savingDefaultOrg: false,
      showMfaDialog: false,
      orgSearch: '' as string,
    };
  },
  computed: {
    // Same threshold as the full-page picker (OrgPicker.vue, DOCB-13836):
    // below it the list is faster to scan than to type into.
    showOrgSearch(): boolean {
      return this.organisations.length > ORG_SEARCH_THRESHOLD;
    },
    filteredOrganisations(): MeOrganisationItem[] {
      // q-input with `clearable` writes null (not '') on clear.
      const term = (this.orgSearch ?? '').trim().toLowerCase();
      if (!term) return this.organisations;
      return this.organisations.filter((org) => {
        const name = (org.name ?? '').toLowerCase();
        const region = (org.region ?? '').toLowerCase();
        return name.includes(term) || region.includes(term);
      });
    },
    // Non-empty only while the current pick is filtered OUT of view — Save
    // still acts on it, so the user must be told what they are about to save.
    hiddenDefaultOrgName(): string {
      if (!this.selectedDefaultOrgId) return '';
      if (this.filteredOrganisations.some((org) => org.org_id === this.selectedDefaultOrgId)) {
        return '';
      }
      const selected = this.organisations.find((o) => o.org_id === this.selectedDefaultOrgId);
      return selected?.name ?? '';
    },
  },
  emits: ['refreshClicked', 'popClosed'],
  components: {
    MfaSettings,
    DualMonitor,
    fontSizeOption,
    // darkModeOption,
    DateFormat,
    AmountFormat,
  },
  setup() {
    const user_store = useUserStore();
    const { updateUserName } = user_store;
    const { sub_org_id, main_orgainzation } = storeToRefs(user_store);

    return {
      user_store,
      sub_org_id,
      updateUserName,
      main_orgainzation,
      model: ref({} as { [k: string]: any }),
      model_error: ref({} as { [k: string]: any }),
      processing: ref(false),
      api_errors: ref(''),
      api_success: ref(''),
      show_password: ref(false),
      show_confirm_password: ref(false),
      show_current_password: ref(false),
      saveClose: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.initModel();
    this.updateModelFromSettings();
    this.loadOrganisations();
  },
  methods: {
    async loadOrganisations() {
      try {
        const { userApiService } = await import('src/services');
        const response = await userApiService.getMyOrganisations();
        this.organisations = response?.organisations ?? [];
        const current = this.organisations.find((o) => o.is_default);
        this.currentDefaultOrgId = current?.org_id ?? '';
        this.selectedDefaultOrgId = this.currentDefaultOrgId;
        // The list is a bounded scroll container now (DOCB-13836) — without
        // this the current default sits off-screen for users far down the
        // alphabet, and the section looks like nothing is selected.
        void this.$nextTick(() => {
          const items = this.$el?.querySelectorAll?.('[data-test^="default-org-item-"]');
          if (!items) return;
          const target = Array.from(items as NodeListOf<HTMLElement>).find(
            (el) => el.getAttribute('data-test') === `default-org-item-${this.selectedDefaultOrgId}`,
          );
          target?.scrollIntoView?.({ block: 'nearest' });
        });
      } catch (err) {
        logError(err);
        this.organisations = [];
      }
    },

    async saveDefaultOrg() {
      if (
        !this.selectedDefaultOrgId ||
        this.selectedDefaultOrgId === this.currentDefaultOrgId
      ) {
        return;
      }
      this.savingDefaultOrg = true;
      try {
        const { userApiService } = await import('src/services');
        await userApiService.setDefaultOrg(this.selectedDefaultOrgId);
        this.currentDefaultOrgId = this.selectedDefaultOrgId;
        this.organisations = this.organisations.map((org) => ({
          ...org,
          is_default: org.org_id === this.selectedDefaultOrgId,
        }));
        notify.success(this.$t('default_org_updated') as string);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.savingDefaultOrg = false;
      }
    },

    initModel() {
      for (const field_name of this.fields) {
        this.model[field_name] = '';
        this.model_error[field_name] = '';
      }

      this.resetErrors();
    },
    updateModelFromSettings() {
      for (const field_name of this.fields) {
        const field_value = getUserDetailFromkey(field_name);
        this.model[field_name] = field_value;
      }
    },

    resetErrors() {
      for (const field_name of this.fields) {
        this.model_error[field_name] = '';
      }
      this.api_errors = '';
      this.api_success = '';
    },

    validateRow() {
      let error = false;
      this.resetErrors();
      for (const field_name of this.empty_validation_fields) {
        if (!this.model[field_name] || this.model[field_name].length == 0) {
          error = true;
          this.model_error[field_name] = this.$t(field_name) + ' is required';
        }
      }

      if (
        !this.isPasswordEmpty() &&
        !this.isValidPassword(this.model['password'])
      ) {
        this.model_error['password'] = this.$t('password_hint');
        error = true;
      }

      if (!error && this.model['password'] !== this.model['confirm_password']) {
        this.model_error['confirm_password'] = 'Passwords do not match';
        error = true;
      }

      // DOCB-10998: the token-scoped change-password endpoint requires proof
      // of the current password.
      if (
        !error &&
        !this.isPasswordEmpty() &&
        (!this.model['current_password'] ||
          this.model['current_password'].length === 0)
      ) {
        this.model_error['current_password'] =
          this.$t('current_password') + ' is required';
        error = true;
      }

      return error;
    },
    isPasswordEmpty() {
      if (this.model['password'] && this.model['password'].length !== 0) {
        return false;
      }
      return true;
    },
    isValidPassword(password: any) {
      if (!password || password.trim().length === 0) {
        return false;
      }

      return passwordPattern.test(password);
    },

    async updateUserInfo() {
      if (this.isPasswordEmpty()) {
        delete this.model['password'];
        delete this.model['confirm_password'];
      }
      if (this.validateRow()) {
        return;
      }
      try {
        let user_id = getUserDetailFromkey('id');
        if (!user_id) {
          throw { message: 'User ID is missing' };
        }

        this.processing = true;
        await this.editUser(user_id);
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.processing = false;
      }
    },

    async editUser(user_id: string) {
      let message = this.$t('user_updated');

      // DOCB-10998: the password change goes through the token-scoped
      // /v2/me/change-password endpoint, NOT the admin PUT /user/<id>. The
      // admin route is identified by a client-supplied user id; whenever that
      // id and the token principal disagreed (stale LocalStorage id, org
      // switch, duplicate rows), a superadmin's SELF-edit was indistinguishable
      // from "admin edits another superadmin" and was rejected with
      // CANT_CHANGE_SUPER_ADMIN_ACCOUNT. The me-endpoint takes identity from
      // the token only and requires current-password proof — structurally
      // immune to that misclassification, and a security improvement.
      if (!this.isPasswordEmpty()) {
        try {
          await getMe().postV2MeChangePassword({
            current_password: this.model['current_password'],
            new_password: this.model['password'],
            new_password_confirm: this.model['confirm_password'],
          });
        } catch (pwError: any) {
          const detail =
            pwError?.response?.data?.message ||
            pwError?.message ||
            this.$t('password_hint');
          this.model_error['current_password'] = detail;
          throw { message: detail };
        }
      }

      let formData = new FormData();

      formData.append('first_name', this.model['first_name']);
      formData.append('last_name', this.model['last_name']);
      formData.append('org_id', getOrgId());

      let token: string = await getAuthorizationToken();
      let result: any;
      result = await axios.put(api.update_user + user_id, formData, {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Authorization: token,
        },
      });
      if (result.data.success === false && result.data.message) {
        message = '';
        if (
          result.data.error_code &&
          this.$t(result.data.error_code) !== result.data.error_code
        ) {
          message = this.$t(result.data.error_code);
        } else {
          message = this.$t(result.data.message);
        }

        throw { message: message };
      }

      const user_settings: any = LocalStorage.getItem('user_details');
      if (user_settings) {
        user_settings.first_name = this.model['first_name'];
        user_settings.last_name = this.model['last_name'];
        LocalStorage.set('user_details', user_settings);
        this.updateUserName();
      }
      notify.success(message);
    },

    handleErrors(error: any) {
      let msg = '';

      if (
        error != null &&
        typeof error == 'object' &&
        error.hasOwnProperty('message')
      ) {
        msg = error.message;
      }

      if (
        error &&
        error.response &&
        error.response.data &&
        error.response.data.hasOwnProperty('message')
      ) {
        msg = error.response.data.message;
      }

      if (!msg || msg === '') {
        return;
      }

      this.api_errors = msg;
      throw { message: msg };
    },
  },
});
</script>

<style scoped>
.organizations-list {
  padding-bottom: 8px;
}

.default-org-list .q-item {
  min-height: 40px;
}

/* DOCB-13836: cap the list at ~5 rows and let it scroll on its own.
   Unbounded, a 28-org membership stretched the dialog until the Save button
   (and everything below it) was pushed out of reach. 5 * 40px row height. */
.default-org-list {
  max-height: 200px;
  overflow-y: auto;
  overscroll-behavior: contain;
}
</style>
