/**
 * Sidebar Preferences Store
 *
 * Manages user customization of sidebar menu items:
 * - Custom ordering via drag-and-drop
 * - Show/hide individual items
 * - Pinned items always appear at top
 *
 * Persisted in localStorage per-user. Layered on top of the dynamic
 * feature-flag-based menu from SideMenu.vue's prepareMenuItems().
 */

import { defineStore } from 'pinia';

// ─── Types ───────────────────────────────────────────────────────────

export interface SidebarItemPreference {
  itemId: string;
  order: number;
  visible: boolean;
  pinned: boolean;
}

export interface SidebarPreferencesState {
  preferences: SidebarItemPreference[];
  editMode: boolean;
  initialized: boolean;
}

export interface MenuItem {
  label: string;
  name: string;
  icon: string | object;
  separator: boolean;
  to: string;
}

// ─── Constants ───────────────────────────────────────────────────────

const STORAGE_KEY = 'docbits_sidebar_preferences';

// ─── Store ───────────────────────────────────────────────────────────

export const useSidebarPreferencesStore = defineStore('sidebarPreferences', {
  state: (): SidebarPreferencesState => ({
    preferences: [],
    editMode: false,
    initialized: false,
  }),

  getters: {
    /** Get preference for a specific menu item */
    getPreference:
      (state) =>
      (itemId: string): SidebarItemPreference | undefined => {
        return state.preferences.find((p) => p.itemId === itemId);
      },

    /** Check if user has any custom preferences saved */
    hasCustomPreferences: (state): boolean => {
      return state.preferences.length > 0;
    },
  },

  actions: {
    /**
     * Initialize preferences from localStorage.
     * Called once when sidebar first mounts.
     */
    initialize() {
      if (this.initialized) return;

      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          const parsed = JSON.parse(stored);
          if (Array.isArray(parsed)) {
            this.preferences = parsed;
          }
        }
      } catch {
        // Corrupted data — start fresh
        this.preferences = [];
      }

      this.initialized = true;
    },

    /**
     * Apply user preferences to a list of menu items.
     * Returns a new array sorted/filtered according to preferences.
     * Items not in preferences are appended at the end (new features).
     */
    applyPreferences(menuItems: MenuItem[]): MenuItem[] {
      if (this.preferences.length === 0) {
        return menuItems;
      }

      const result: MenuItem[] = [];
      const remaining = [...menuItems];

      // First pass: add items in preference order
      const sortedPrefs = [...this.preferences].sort((a, b) => a.order - b.order);

      for (const pref of sortedPrefs) {
        const idx = remaining.findIndex((item) => item.name === pref.itemId);
        if (idx === -1) continue; // Item not in current menu (feature flag off)

        if (pref.visible) {
          result.push(remaining[idx]);
        }
        remaining.splice(idx, 1);
      }

      // Second pass: append any new items not in preferences (new features)
      result.push(...remaining);

      // Move pinned items to the top
      const pinned: MenuItem[] = [];
      const unpinned: MenuItem[] = [];

      for (const item of result) {
        const pref = this.preferences.find((p) => p.itemId === item.name);
        if (pref?.pinned) {
          pinned.push(item);
        } else {
          unpinned.push(item);
        }
      }

      return [...pinned, ...unpinned];
    },

    /**
     * Import the default order from the current menu items.
     * Only called when user has no saved preferences yet.
     */
    importDefaults(menuItems: MenuItem[]) {
      if (this.preferences.length > 0) return;

      this.preferences = menuItems.map((item, index) => ({
        itemId: item.name,
        order: index,
        visible: true,
        pinned: false,
      }));

      this.persist();
    },

    /**
     * Update the order of all items based on a reordered name list.
     */
    reorder(orderedNames: string[]) {
      for (let i = 0; i < orderedNames.length; i++) {
        const pref = this.preferences.find((p) => p.itemId === orderedNames[i]);
        if (pref) {
          pref.order = i;
        } else {
          // New item — add preference
          this.preferences.push({
            itemId: orderedNames[i],
            order: i,
            visible: true,
            pinned: false,
          });
        }
      }

      this.persist();
    },

    /**
     * Toggle visibility for a specific item.
     */
    toggleVisibility(itemId: string) {
      const pref = this.preferences.find((p) => p.itemId === itemId);
      if (pref) {
        pref.visible = !pref.visible;
      } else {
        this.preferences.push({
          itemId,
          order: this.preferences.length,
          visible: false,
          pinned: false,
        });
      }
      this.persist();
    },

    /**
     * Toggle pin status for a specific item.
     */
    togglePin(itemId: string) {
      const pref = this.preferences.find((p) => p.itemId === itemId);
      if (pref) {
        pref.pinned = !pref.pinned;
      } else {
        this.preferences.push({
          itemId,
          order: this.preferences.length,
          visible: true,
          pinned: true,
        });
      }
      this.persist();
    },

    /**
     * Set visibility for a specific item.
     */
    setVisibility(itemId: string, visible: boolean) {
      const pref = this.preferences.find((p) => p.itemId === itemId);
      if (pref) {
        pref.visible = visible;
      } else {
        this.preferences.push({
          itemId,
          order: this.preferences.length,
          visible,
          pinned: false,
        });
      }
      this.persist();
    },

    /**
     * Reset all preferences to defaults.
     */
    resetToDefaults() {
      this.preferences = [];
      this.persist();
    },

    /**
     * Toggle edit mode.
     */
    setEditMode(value: boolean) {
      this.editMode = value;
    },

    /**
     * Persist preferences to localStorage.
     */
    persist() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(this.preferences));
      } catch {
        // localStorage full — silently fail
      }
    },
  },
});
