const GENERIC_SUPPORT_TICKET_ERROR = 'Failed to send report. Please try again.';

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function getNestedPayload(error: unknown): unknown {
  if (!isRecord(error)) return error;

  const response = error.response;
  if (isRecord(response) && response.data !== undefined) {
    return response.data;
  }

  const metadata = error.metadata;
  if (
    isRecord(metadata) &&
    isRecord(metadata.response) &&
    metadata.response.data !== undefined
  ) {
    return metadata.response.data;
  }

  return error;
}

function compactMessage(value: unknown): string {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value.trim();
  if (Array.isArray(value)) {
    return value.map(compactMessage).filter(Boolean).join('; ');
  }
  if (isRecord(value)) {
    for (const key of ['error', 'message', 'detail', 'errors']) {
      const message = compactMessage(value[key]);
      if (message) return message;
    }
  }
  return '';
}

export function formatSupportTicketErrorMessage(error: unknown): string {
  const payload = getNestedPayload(error);
  const payloadRecord = isRecord(payload) ? payload : undefined;
  const detail = compactMessage(payloadRecord?.detail);

  if (detail === 'customer') {
    return 'Email not recognized. Please use your DocBits account email.';
  }

  const message =
    compactMessage(payloadRecord?.message) ||
    compactMessage(payloadRecord?.error) ||
    (!payloadRecord ? compactMessage(payload) : '') ||
    (isRecord(error) ? compactMessage(error.message) : '');

  if (message) {
    return message.length > 300 ? `${message.slice(0, 297)}...` : message;
  }

  if (detail === 'zammad_timeout') {
    return 'Support ticket could not be created because the support system did not respond in time. Please try again in a moment.';
  }

  if (detail === 'zammad' || detail === 'zammad_unreachable') {
    return 'Support ticket could not be created. Please try again in a moment.';
  }

  return GENERIC_SUPPORT_TICKET_ERROR;
}
